import java.io.*;
import java.net.*;
import java.util.*;
import com.sun.net.httpserver.*;

public class ReportGenerator implements HttpHandler {

    private static final String TEMPLATE_DIR = "/opt/reports/templates/";
    private static final Set<String> ALLOWED_FORMATS = Set.of("pdf", "csv", "xlsx");

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/reports/generate", new ReportGenerator());
        server.createContext("/api/reports/preview", new ReportPreview());
        server.setExecutor(null);
        server.start();
    }

    @Override
    public void handle(HttpExchange exchange) throws IOException {
        if (!"POST".equals(exchange.getRequestMethod())) {
            exchange.sendResponseHeaders(405, 0);
            exchange.close();
            return;
        }

        Map<String, String> params = parseBody(exchange.getRequestBody());
        String templateName = params.getOrDefault("template", "default");
        String format = params.getOrDefault("format", "pdf");
        String clientId = params.getOrDefault("client_id", "unknown");

        // Validate format
        if (!ALLOWED_FORMATS.contains(format.toLowerCase())) {
            sendResponse(exchange, 400, "{\"error\": \"Invalid format\"}");
            return;
        }

        // Validate template name - allow alphanumeric, hyphens, dots, slashes for subdirs
        if (!templateName.matches("[a-zA-Z0-9._/-]+")) {
            sendResponse(exchange, 400, "{\"error\": \"Invalid template name\"}");
            return;
        }

        // Construct template path
        String templatePath = TEMPLATE_DIR + templateName + ".xml";
        File templateFile = new File(templatePath);

        // Check file exists
        if (!templateFile.exists()) {
            sendResponse(exchange, 404, "{\"error\": \"Template not found\"}");
            return;
        }

        // Read template content
        String content;
        try (BufferedReader reader = new BufferedReader(new FileReader(templateFile))) {
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                sb.append(line).append("\n");
            }
            content = sb.toString();
        } catch (IOException e) {
            sendResponse(exchange, 500, "{\"error\": \"Failed to read template\"}");
            return;
        }

        // Replace placeholders
        content = content.replace("{{CLIENT_ID}}", clientId);
        content = content.replace("{{GENERATED_AT}}", new Date().toString());
        content = content.replace("{{FORMAT}}", format);

        String response = "{\"status\": \"generated\", \"template\": \"" + templateName + "\", \"size\": " + content.length() + "}";
        sendResponse(exchange, 200, response);
    }

    private Map<String, String> parseBody(InputStream body) throws IOException {
        Map<String, String> params = new HashMap<>();
        BufferedReader reader = new BufferedReader(new InputStreamReader(body));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) sb.append(line);
        String raw = sb.toString();
        for (String pair : raw.split("&")) {
            String[] kv = pair.split("=", 2);
            if (kv.length == 2) {
                params.put(URLDecoder.decode(kv[0], "UTF-8"), URLDecoder.decode(kv[1], "UTF-8"));
            }
        }
        return params;
    }

    private void sendResponse(HttpExchange exchange, int code, String body) throws IOException {
        byte[] bytes = body.getBytes("UTF-8");
        exchange.getResponseHeaders().set("Content-Type", "application/json");
        exchange.sendResponseHeaders(code, bytes.length);
        exchange.getResponseBody().write(bytes);
        exchange.close();
    }
}

class ReportPreview implements HttpHandler {
    @Override
    public void handle(HttpExchange exchange) throws IOException {
        // Preview endpoint - returns template metadata
        String query = exchange.getRequestURI().getQuery();
        String templateName = "default";
        if (query != null) {
            for (String param : query.split("&")) {
                String[] kv = param.split("=", 2);
                if (kv.length == 2 && "template".equals(kv[0])) {
                    templateName = URLDecoder.decode(kv[1], "UTF-8");
                }
            }
        }
        String response = "{\"template\": \"" + templateName + "\", \"available\": true}";
        byte[] bytes = response.getBytes("UTF-8");
        exchange.getResponseHeaders().set("Content-Type", "application/json");
        exchange.sendResponseHeaders(200, bytes.length);
        exchange.getResponseBody().write(bytes);
        exchange.close();
    }
}
